package com.taskflow.api;
import com.taskflow.model.*;import com.taskflow.repo.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static com.taskflow.api.ApiDtos.*;
@RestController @RequestMapping("/api") public class TaskController extends BaseController{
 private final TaskRepository tasks;private final ProjectController projects;private final UserRepository users;private final CommentRepository comments;
 public TaskController(TaskRepository t,ProjectController p,UserRepository u,CommentRepository c){tasks=t;projects=p;users=u;comments=c;}
 @GetMapping("/projects/{projectId}/tasks") PageView<TaskView> list(@PathVariable Long projectId,@RequestParam(required=false) TaskStatus status,@RequestParam(required=false) Priority priority,@RequestParam(required=false) Long assigneeId,@RequestParam(required=false) String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="createdAt,desc") String sort){projects.expanded(projectId);String[] s=sort.split(",");String field=Set.of("createdAt","updatedAt","dueDate","priority","title","status").contains(s[0])?s[0]:"createdAt";Sort.Direction d=s.length>1&&s[1].equalsIgnoreCase("asc")?Sort.Direction.ASC:Sort.Direction.DESC;Page<Task> result=tasks.search(projectId,status,priority,assigneeId,q==null||q.isBlank()?null:q,PageRequest.of(Math.max(0,page),Math.max(1,Math.min(100,size)),Sort.by(d,field)));return new PageView<>(result.getContent().stream().map(this::view).toList(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages(),result.isFirst(),result.isLast());}
 @PostMapping("/projects/{projectId}/tasks") TaskView create(@PathVariable Long projectId,@Valid @RequestBody TaskRequest r){Project p=projects.expanded(projectId);AppUser a=r.assigneeId()==null?null:users.findById(r.assigneeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assignee not found."));Task t=new Task(r.title().trim(),r.description(),r.priority()==null?Priority.MEDIUM:r.priority(),p,a,me(),r.dueDate());if(r.status()!=null)t.status=r.status();return view(tasks.save(t));}
 @PutMapping("/tasks/{id}") TaskView update(@PathVariable Long id,@Valid @RequestBody TaskRequest r){Task t=expanded(id);if(r.assigneeId()!=null)t.assignee=users.findById(r.assigneeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assignee not found."));else t.assignee=null;t.title=r.title().trim();t.description=r.description();if(r.priority()!=null)t.priority=r.priority();if(r.status()!=null)t.status=r.status();t.dueDate=r.dueDate();return view(tasks.save(t));}
 @PatchMapping("/tasks/{id}/status") TaskView status(@PathVariable Long id,@RequestBody Map<String,String> body){Task t=expanded(id);try{t.status=TaskStatus.valueOf(body.get("status"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a valid task status.");}return view(tasks.save(t));}
 @DeleteMapping("/tasks/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){Task t=expanded(id);if(me().role==Role.MEMBER&&!Objects.equals(t.creator.id,me().id)&&!(t.assignee!=null&&Objects.equals(t.assignee.id,me().id)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot delete this task.");tasks.delete(t);}
 @GetMapping("/tasks/{id}/comments") List<CommentView> comments(@PathVariable Long id){expanded(id);return comments.findForTask(id).stream().map(c->new CommentView(c.id,c.body,UserView.of(c.author),c.createdAt)).toList();}
 @PostMapping("/tasks/{id}/comments") CommentView comment(@PathVariable Long id,@Valid @RequestBody CommentRequest r){Task t=expanded(id);TaskComment c=comments.save(new TaskComment(t,me(),r.body().trim()));return new CommentView(c.id,c.body,UserView.of(me()),c.createdAt);}
 Task expanded(Long id){Task t=tasks.findExpandedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found."));projects.expanded(t.project.id);return t;}
 TaskView view(Task t){return new TaskView(t.id,t.title,t.description,t.status,t.priority,t.project.id,t.project.name,t.assignee==null?null:UserView.of(t.assignee),UserView.of(t.creator),t.dueDate,t.createdAt,t.updatedAt);}
}
